"""Scatter of primitive Pythagorean triples (legs), colored by a multiplicative coloring."""
import matplotlib.pyplot as plt
from math import gcd

def color_of(n, k, prime_color):
    total, m, d = 0, n, 2
    while d * d <= m:
        while m % d == 0:
            total += prime_color.get(d, 0); m //= d
        d += 1
    if m > 1: total += prime_color.get(m, 0)
    return total % k

def prim_triples(limit):
    out = []
    m = 2
    while m*m <= limit:
        for n in range(1, m):
            if (m-n) % 2 == 1 and gcd(m, n) == 1:
                x, y, z = m*m-n*n, 2*m*n, m*m+n*n
                if z <= limit: out.append((x, y, z))
        m += 1
    return out

k = 3
prime_color = {2:1, 3:2, 5:1, 7:2, 11:0}
T = prim_triples(400)
xs = [t[0] for t in T]; ys = [t[1] for t in T]
cs = [color_of(t[2], k, prime_color) for t in T]
plt.figure(figsize=(6,6))
sc = plt.scatter(xs, ys, c=cs, cmap='viridis', s=30)
plt.colorbar(sc, label='color of hypotenuse')
plt.xlabel('leg x'); plt.ylabel('leg y')
plt.title('Primitive Pythagorean triples, hypotenuse colored by f')
plt.tight_layout(); plt.savefig('triples_scatter.png', dpi=150)
